import {readAuthoring,conditionMet,conditionIssues,findEvent} from './authoring-model.js';
import {questReadSource} from './quest-runtime.js';
export const HM_RULES={cut:{name:'Cut',move:15,hmItem:339,badge:2},fly:{name:'Fly',move:19,hmItem:340,badge:3},surf:{name:'Surf',move:57,hmItem:341,badge:5},strength:{name:'Strength',move:70,hmItem:342,badge:4},flash:{name:'Flash',move:148,hmItem:343,badge:1},rocksmash:{name:'Rock Smash',move:249,hmItem:344,badge:6},waterfall:{name:'Waterfall',move:127,hmItem:345,badge:7},dive:{name:'Dive',move:291,hmItem:346,badge:8}};
export const HM_MODES={party:'Move taught to a party Pokémon',hm:'HM in the bag — no teaching',item:'Replacement item in the bag',free:'No move or item required',disabled:'Disabled'};
export function hmRule(project,effect){return project?.hmRules?.moves?.[effect]||{mode:'party',conditions:[{kind:'badge',badge:HM_RULES[effect]?.badge}]};}
export function hasHMRules(project){return !!Object.keys(project.hmRules?.moves||{}).length;}
export function hmNeedsQuest(project){return Object.values(project.hmRules?.moves||{}).some(r=>r.conditions.some(c=>['flag','event','variable','option'].includes(c.kind)));}
export function validateHMRules(project){const rules=project.hmRules;if(rules===undefined)return;if(!rules||rules.version!==1||!rules.moves||Array.isArray(rules.moves)||Object.keys(rules.moves).length>8)throw Error('Invalid global HM settings.');for(const [effect,r]of Object.entries(rules.moves)){if(!HM_RULES[effect]||!r||!Object.hasOwn(HM_MODES,r.mode)||!Array.isArray(r.conditions)||r.conditions.length>8)throw Error('Invalid global HM rule.');if(r.mode==='item'&&!(r.itemRef?readAuthoring(project).items.some(i=>i.id===r.itemRef):Number.isInteger(r.itemId)&&r.itemId>0&&r.itemId<=65535))throw Error('Choose a replacement item.');for(const c of r.conditions){if(!['badge','event','flag','variable','option'].includes(c.kind)||conditionIssues(c,project).length)throw Error('An HM prerequisite is missing or invalid.');if(['variable','option'].includes(c.kind)){const v=readAuthoring(project).variables.find(v=>v.id===c.variableId);if(!['eq','ne','gt','ge','lt','le'].includes(c.operator)||!Number.isInteger(c.value)||c.value<0||c.value>=2**v.bits)throw Error('Choose a valid quest stage comparison.');}if(['event','flag'].includes(c.kind)&&c.value!==undefined&&typeof c.value!=='boolean')throw Error('Choose whether the prerequisite is completed or unset.');if(c.kind==='event'&&findEvent(project,c.eventId)?.n.runtime?.action!=='scene')throw Error('An HM event prerequisite must use a saved visual scene.');}}}
export function hmAllowed(project,effect,state={}){const r=hmRule(project,effect),h=HM_RULES[effect];if(!h||r.mode==='disabled'||!r.conditions.every(c=>conditionMet(c,project,state)))return false;if(r.mode==='party')return !!state.hmMoves?.has(effect);if(r.mode==='free')return true;return (state.bag?.get(r.mode==='hm'?h.hmItem:r.itemRef||r.itemId)||0)>0;}
export function hmRuleSummary(project,effect){const r=hmRule(project,effect);return HM_MODES[r.mode]+(r.mode==='item'?' · '+(readAuthoring(project).items.find(i=>i.id===r.itemRef)?.name||'item '+r.itemId):'')+' · '+(r.conditions.length?r.conditions.length+' prerequisite'+(r.conditions.length===1?'':'s'):'no prerequisites');}
export function hmRequirementSource(project,effect,{questRuntime,itemIds=new Map(),fail='@blocked',prefix='@hm_rule'}={}){
 const rule=hmRule(project,effect),h=HM_RULES[effect],code=[];if(!h)throw Error('Unknown field move.');if(rule.mode==='disabled')return['goto '+fail];
 const slot=id=>{const q=project.questFlags?.find(q=>q.id===id);if(!q)throw Error('The HM prerequisite has no saved flag.');return q.slot;};
 for(const [index,c]of rule.conditions.entries()){
  if(c.kind==='badge')code.push('checkflag '+(0x81f+Number(c.badge)),'goto_if 0 '+fail);
  else if(['flag','event'].includes(c.kind)){const id=c.kind==='event'?findEvent(project,c.eventId)?.n.runtime?.completionFlag:c.flagId;code.push(...questReadSource(questRuntime,slot(id),fail),'compare_var_to_value 0x800D '+(c.value===false?0:1),'goto_if 5 '+fail);}
  else{const v=readAuthoring(project).variables.find(v=>v.id===c.variableId);if(!v)throw Error('The HM quest counter is missing.');code.push('setvar 0x800A 0');for(let bit=0;bit<v.bits;bit++){const skip=prefix+'_'+index+'_'+bit;code.push(...questReadSource(questRuntime,slot(v.bitIds[bit]),fail),'compare_var_to_value 0x800D 0','goto_if 1 '+skip,'addvar 0x800A '+2**bit,skip+':');}const pass=prefix+'_'+index+'_pass';code.push('compare_var_to_value 0x800A '+c.value,'goto_if '+({eq:1,ne:5,gt:2,ge:4,lt:0,le:3}[c.operator])+' '+pass,'goto '+fail,pass+':');}
 }
 if(rule.mode==='party')code.push('checkpartymove '+h.move,'compare_var_to_value 0x800D 6','goto_if 1 '+fail);
 else if(rule.mode!=='free'){const id=rule.mode==='hm'?h.hmItem:rule.itemRef?itemIds.get(rule.itemRef):rule.itemId;if(!Number.isInteger(id))throw Error('Bind the replacement HM item to a native item slot first.');code.push('checkitem '+id+' 1','compare_var_to_value 0x800D 1','goto_if 5 '+fail,'setvar 0x800D 0');}
 else code.push('setvar 0x800D 0');return code;
}
